import { TruncateStringProps } from '@ds/truncate-string';
import { PolymorphicRef, ValueOf, WithSupportProps } from '@ds/utils';
import { ComponentPropsWithoutRef, ElementType } from 'react';

import { APPEARANCE, ROLE_APPEARANCE } from './constants';

export type Appearance = ValueOf<typeof APPEARANCE>;

export type RoleAppearance = ValueOf<typeof ROLE_APPEARANCE>;

export type BaseProps = WithSupportProps<{
  /** Текст ссылки */
  label?: string;
  /** Роль, в которой применяется `appearance`: обычный текст или текст на акцентной подложке
   * @default 'regular'
   */
  roleAppearance?: RoleAppearance;
  /** Семантический цвет
   * @default 'primary'
   */
  appearance?: Appearance;
  /** Находится ли ссылка внутри текста (и можно ли её переносить) */
  insideText?: boolean;
  /**
   * Вариант обрезания строки:
   * <br/> - `end` - с конца;
   * <br/> - `middle` - посередине
   * */
  truncateVariant?: TruncateStringProps['variant'];
  /** Наличие нижнего подчеркивания
   * @default false
   */
  underlined?: boolean;
}>;

export type LinkProps<T extends ElementType = 'a'> = BaseProps & {
  /**
   *
   * Полиморфный компонент.
   *
   * Оформить переданный компонент или html элемент в стиль ссылки.
   *
   * Список атрибутов, которые переданный компонент должен принять:
   * <br/> - `className`
   * <br/> - `data-size`
   * <br/> - `data-text-mode`
   * <br/> - `data-appearance`
   * <br/> - `data-inside-text`
   *
   * @type ComponentType | ElementType
   * @default 'a'
   *
   * */
  as?: T;
  /**
   * Ref на реальный DOM-элемент/инстанс, который рендерится через `as`.
   * Используем явный проп, чтобы не зависеть от `forwardRef` и не тащить type-assertions на экспорт.
   */
  innerRef?: PolymorphicRef<T>;
} & Omit<ComponentPropsWithoutRef<ElementType extends T ? 'a' : T>, keyof BaseProps>;

export type PickLinkProps<T extends ElementType, SelectedKeys extends keyof LinkProps<T>> = Pick<
  LinkProps<T>,
  SelectedKeys
> &
  Omit<ComponentPropsWithoutRef<ElementType extends T ? 'a' : T>, keyof BaseProps>;
